/*
 * Meridian base styles — shared across every `@designharness/ui` component.
 *
 * Selectivity budget (TOKEN-API.md §5): no selector may exceed (0,2,0). The frozen
 * anatomy contract gives us `data-scope` + `data-part` on every part, which is already
 * (0,2,0), so the scope is always asserted through `:where([data-scope="…"])`, which
 * contributes zero specificity and leaves the full budget for state attributes and
 * pseudo-classes. `!important` is banned by the harness sensor, so cascade order is
 * managed with source order and layer order instead (see `styles.css`).
 *
 * Every colour, space, radius, shadow, duration and type declaration below is a
 * `var(--…)` reference into the compiled token artifact (TOKEN-API.md §3).
 */

@layer components {
  /*
   * `color-scheme` is declared per component root, not on `:root` (the token artifact
   * owns that): native scrollbars, the text caret and the selection checkbox then follow
   * the same mode the semantic tokens flipped to (RESEARCH.md §6.3).
   */
  [data-part="root"]:where([data-scope="button"]),
  [data-part="root"]:where([data-scope="input"]),
  [data-part="root"]:where([data-scope="combobox"]),
  [data-part="root"]:where([data-scope="table"]),
  [data-part="content"]:where([data-scope="dialog"]) {
    color-scheme: light dark;
  }

  /*
   * One focus ring for every interactive part. `--color-focus` is a semantic role, so the
   * ring is dark-blue in light mode, light-blue in dark mode and pure black/white in high
   * contrast without a single mode-specific selector; `--border-width-strong` keeps it
   * above the WCAG 2.2 SC 1.4.11 non-text threshold.
   */
  [data-part="root"]:where([data-scope="button"]):focus-visible,
  [data-part="input"]:where([data-scope="input"]):focus-visible,
  [data-part="input"]:where([data-scope="combobox"]):focus-visible,
  [data-part="search-field"]:focus-visible,
  [data-part="select"]:focus-visible,
  [data-part="item"]:focus-visible,
  [data-part="first-trigger"]:focus-visible,
  [data-part="prev-trigger"]:focus-visible,
  [data-part="next-trigger"]:focus-visible,
  [data-part="last-trigger"]:focus-visible,
  [data-part="trigger"]:where([data-scope="dialog"]):focus-visible,
  [data-part="close-trigger"]:focus-visible,
  .dh-combobox__trigger:focus-visible,
  .dh-combobox__clear:focus-visible,
  [data-part="columnheader"] button:focus-visible {
    outline: var(--border-width-strong) solid var(--color-focus);
    outline-offset: calc(var(--space-xxs) / 2);
    border-radius: var(--radius-sm);
  }

  /*
   * Focus rings are the *only* ring in the system: a hairline `--color-border-selected`
   * seam marks the currently selected control so state is never carried by colour alone
   * (DESIGN.md "Colors").
   */
  [data-part="option"][aria-selected="true"]:where([data-scope="combobox"]) {
    border-inline-start-color: var(--color-border-selected);
  }

  /* Text selection stays inside the neutral scale — colour is a state, not an ornament. */
  [data-part="root"]:where([data-scope="table"]) ::selection {
    background-color: var(--color-primary-subtle);
    color: var(--color-on-primary-subtle);
  }
}

/*
 * Reduced-motion contract (WCAG 2.2 SC 2.3.3, DESIGN.md "Don'ts").
 *
 * This lives in its own cascade layer declared *after* `components`, so it wins by layer
 * order rather than by specificity or `!important` (both banned by the harness sensor).
 * Motion degrades to an instant opacity change: durations collapse to
 * `--duration-instant` and the only transforms this layer authors (the spinners) are
 * switched off. The machine's own inline popper transform is positioning, not motion, and
 * is deliberately left alone.
 */

@layer motion {
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      transition-duration: var(--duration-instant);
      animation-duration: var(--duration-instant);
      animation-delay: var(--duration-instant);
      animation-iteration-count: 1;
      scroll-behavior: auto;
    }

    .dh-button__spinner,
    .dh-combobox__spinner {
      animation-name: none;
      transform: none;
      rotate: none;
    }

    [data-part="content"]:where([data-scope="combobox"]),
    [data-part="content"]:where([data-scope="dialog"]) {
      transform: none;
    }

    [data-part="row"]:where([data-scope="table"]) {
      transition-property: opacity;
    }
  }
}

/**
 * Class-name helpers for the styled layer.
 *
 * The styled layer's only DOM contribution is *class names*: every structural and
 * state signal (`data-scope`, `data-part`, `data-open`, `data-disabled`, `aria-*`)
 * is owned by `@designharness/primitives` and is never re-implemented, renamed or
 * overridden here (TOKEN-API.md §5). Component CSS is authored against those
 * attributes plus the `dh-<component>` block / `dh-<component>--<variant>` modifier
 * classes produced by these helpers.
 */

/** Any value that a class list may legitimately contain. */
export type ClassValue = string | false | null | undefined;

/** Join a class list, dropping empty entries and collapsing to a single string. */
export function cx(...values: readonly ClassValue[]): string {
  const parts: string[] = [];
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) parts.push(value);
  }
  return parts.join(' ');
}

/**
 * BEM-ish modifier builder: `modifier('dh-button', 'primary')` → `dh-button--primary`.
 * A `false`/`undefined` modifier yields `undefined` so it can be passed to `cx` directly.
 */
export function modifier(block: string, value: string | false | null | undefined): string | undefined {
  if (!value) return undefined;
  return `${block}--${value}`;
}

/**
 * Element builder: `element('dh-button', 'spinner')` → `dh-button__spinner`.
 * Elements are markup *the styled layer itself renders* — never anatomy parts.
 */
export function element(block: string, name: string): string {
  return `${block}__${name}`;
}

/**
 * Merge a consumer `className` after the styled-layer classes so a host app can add
 * utility classes without ever losing the tokenized base (source order, no `!important`).
 */
export function withConsumerClass(styled: string, className: ClassValue): string {
  return cx(styled, className);
}

import type { ReactNode } from 'react';

/**
 * Returns true if the provided ReactNode is present (not undefined, null, false, or empty string).
 */
export const isPresent = (value: ReactNode): boolean =>
  value !== undefined && value !== null && value !== false && value !== '';
